    ["SLC is now active for this group"] = "SLC ist jetzt f\195\188r diese Gruppe aktiv",

    ["SLC stays active for this group - you were handed loot while it was in use."] = "SLC bleibt f\195\188r diese Gruppe aktiv - Euch wurde die Beute \195\188bergeben, w\195\164hrend es verwendet wurde.",
    ["SLC stays active for this raid - you were handed loot while it was in use."] = "SLC bleibt f\195\188r diesen Schlachtzug aktiv - Euch wurde die Beute \195\188bergeben, w\195\164hrend es verwendet wurde.",
    ["Saved per guild. If a rank is renamed, select its new name."] = "Wird pro Gilde gespeichert. Wenn ein Rang umbenannt wird, w\195\164hlt den neuen Namen aus.",
    ["Season started"] = "Saison begonnen",
    ["Seen in your group and stored by player id, so a rename or a realm transfer will not lose them."] = "In Eurer Gruppe gesehen und nach Spieler-ID gespeichert, daher gehen sie bei Umbenennung oder Realmtransfer nicht verloren.",
    ["Selected ranks join your council automatically. Members are included by rank, without adding their names."] = "Gew\195\164hlte R\195\164nge geh\195\182ren automatisch zu Eurem Rat. Mitglieder werden \195\188ber den Rang einbezogen, ohne dass ihre Namen hinzugef\195\188gt werden.",
    ["Semicolon (;) - Excel in German, French and more"] = "Semikolon (;) - Excel auf Deutsch, Franz\195\182sisch und mehr",
    ["Send config"] = "Config senden",
