    ["Show offline"] = "Offline anzeigen",
    ["Show only the awards stored while you were in one guild, or by one of your characters. Older rows, rows imported from other addons and rows stored outside a guild are under No guild."] = "Zeigt nur die Vergaben, die gespeichert wurden, w\195\164hrend Ihr in einer Gilde wart, oder von einem Eurer Charaktere. \195\132ltere Zeilen, aus anderen Addons importierte Zeilen und au\195\159erhalb einer Gilde gespeicherte Zeilen stehen unter \226\128\158Keine Gilde\226\128\156.",
    ["Show the council hover panel"] = "Rats-Tooltip anzeigen",
    ["Show the session frame"] = "Rundenfenster anzeigen",
    ["Show warnings and errors in chat"] = "Warnungen und Fehler im Chat anzeigen",
    ["Shown as the routed player's response on a BoE item, in the colour on the left, with the note BoE. Guild Bank unless you type your own; clear the box to go back to Guild Bank."] = "Wird bei einem BoE-Gegenstand als Antwort des Zielspielers angezeigt, in der Farbe links, mit der Notiz BoE. Gildenbank, solange Ihr keinen eigenen Text eingebt; leert das Feld, um zu \226\128\158Gildenbank\226\128\156 zur\195\188ckzukehren.",
    ["Shows recent awards and other winners for the hovered item."] = "Zeigt k\195\188rzliche Vergaben und andere Gewinner f\195\188r den Gegenstand unter dem Mauszeiger.",
    ["Simple Loot Council is active for this group - %s is collecting the loot for the council."] = "Simple Loot Council ist f\195\188r diese Gruppe aktiv - %s sammelt die Beute f\195\188r den Rat ein.",
    ["Simple Loot Council is active for this group - %s is collecting the loot, and this addon passes your group-loot rolls for the council to distribute."] = "Simple Loot Council ist f\195\188r diese Gruppe aktiv - %s sammelt die Beute ein, und dieses Addon passt bei Euren Gruppenbeute-W\195\188rfen, damit der Rat sie verteilen kann.",
    ["Simple Loot Council is active for this raid - %s is collecting the loot for the council."] = "Simple Loot Council ist f\195\188r diesen Schlachtzug aktiv - %s sammelt die Beute f\195\188r den Rat ein.",
    ["Simple Loot Council is active for this raid - %s is collecting the loot, and this addon passes your group-loot rolls for the council to distribute."] = "Simple Loot Council ist f\195\188r diesen Schlachtzug aktiv - %s sammelt die Beute ein, und dieses Addon passt bei Euren Gruppenbeute-W\195\188rfen, damit der Rat sie verteilen kann.",
    ["SimulationCraft cannot place this item type"] = "SimulationCraft kann diesen Gegenstandstyp nicht einordnen",
    ["Skip the question about taking part and join as soon as the Loot Master starts using Simple Loot Council. You are still told in chat. Never applies while you are the Loot Master."] = "\195\156berspringt die Frage zur Teilnahme und tritt bei, sobald der Beutemeister Simple Loot Council verwendet. Ihr werdet weiterhin im Chat informiert. Gilt nie, solange Ihr selbst Beutemeister seid.",
